export const colorRoles: Record<ColorRole, { purpose: string; usage: string }> = {
  background: { purpose: 'The page ground', usage: 'Body background and full-width sections — commit to it, full-bleed' },
  surface: { purpose: 'Raised or contained areas', usage: 'Cards, form fields, media placeholders; on mid-tone grounds, long body copy sits here' },
  text: { purpose: 'Primary reading color', usage: 'Headlines and body copy' },
  muted: { purpose: 'Secondary information', usage: 'Captions, metadata, helper text, input outlines — never long paragraphs' },
  primary: { purpose: 'Brand ink', usage: 'Primary buttons, key links, logo' },
  secondary: { purpose: 'Supporting tone', usage: 'Secondary buttons, tags, subtle section backgrounds' },
  accent: { purpose: 'The one signal', usage: 'Use in fewer than 5% of pixels: active states, a single highlight per view' },
  border: { purpose: 'Structure lines', usage: 'Hairlines and dividers only (≈1.5:1) — input outlines use muted to meet WCAG 1.4.11' },
}

// Curated for spread, not count: grounds sit in different lightness bands, chroma levels and hue
